<div class="row g-4 health-insurance-premium-calculator-rebuilt"><div class="col-lg-12"><div class="calculator-card"><div class="calculator-body"><div class="row g-3"><div class="col-md-6"><label class="form-label-custom">Age</label><div class="input-group"><input type="number" id="hi-age" class="form-control form-control-lg" value="40" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Plan Tier (1-4)</label><div class="input-group"><input type="number" id="hi-plan" class="form-control form-control-lg" value="2" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Deductible ($)</label><div class="input-group"><span class="input-group-text bg-light fw-bold">$</span><input type="number" id="hi-ded" class="form-control form-control-lg" value="2000" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Coverage (Individual=1, Family=2)</label><div class="input-group"><input type="number" id="hi-cov" class="form-control form-control-lg" value="1" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Smoker Surcharge (%)</label><div class="input-group"><input type="number" id="hi-smoke" class="form-control form-control-lg" value="0" min="0"><span class="input-group-text bg-light fw-bold">%</span></div></div><div class="col-md-6"><label class="form-label-custom">Region Factor (0.8-1.5)</label><div class="input-group"><input type="number" id="hi-region" class="form-control form-control-lg" value="1.0" min="0"></div></div></div></div></div></div><div class="col-lg-12"><div class="output-card-themed" style="--tool-hue:330;--tool-color:#ec4899;--tool-bg:rgba(0,0,0,.02);"><div class="output-hero"><span class="output-hero-label">Health Insurance Premium Calculator</span><div class="output-hero-value" id="health-val">—</div><span class="output-hero-unit" id="health-st">—</span></div><div class="row g-3 mt-3"><div class="col-md-3"><div class="stat-card" style="border-color:#ec4899;background:rgba(0,0,0,.02);"><span class="stat-card-label">ANNUAL PREMIUM</span><span class="stat-card-value" style="color:#ec4899" id="hi-annual">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#3b82f6;background:rgba(0,0,0,.02);"><span class="stat-card-label">MONTHLY</span><span class="stat-card-value" style="color:#3b82f6" id="hi-monthly">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#ef4444;background:rgba(0,0,0,.02);"><span class="stat-card-label">MAX OUT-OF-POCKET</span><span class="stat-card-value" style="color:#ef4444" id="hi-oop">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#22c55e;background:rgba(0,0,0,.02);"><span class="stat-card-label">TOTAL ANNUAL COST</span><span class="stat-card-value" style="color:#22c55e" id="hi-total">—</span></div></div></div><div class="mt-4" id="health-ins"></div><div class="row g-2 mt-4"><div class="col-md-4"><button class="btn d-block mx-auto btn-dark py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="health-cp"><i class="fas fa-copy me-2"></i>Copy Summary</button></div><div class="col-md-4"><button class="btn d-block mx-auto btn-outline-dark py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="health-rs"><i class="fas fa-rotate-left me-2"></i>Reset</button></div><div class="col-md-4"><button class="btn d-block mx-auto btn-outline-primary py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="health-cb"><i class="fas fa-calculator me-2"></i>Calculate</button></div></div></div></div></div>
<script>document.addEventListener("DOMContentLoaded",function(){const $=id=>document.getElementById(id);function fmt(v){return"$"+Math.round(v).toLocaleString();}function calc(){const age=parseFloat($("hi-age").value)||30,plan=parseFloat($("hi-plan").value)||2,ded=parseFloat($("hi-ded").value)||2000,cov=parseFloat($("hi-cov").value)||1,smoke=(parseFloat($("hi-smoke").value)||0)/100,region=parseFloat($("hi-region").value)||1;const baseMonthly=250;const ageFactor=age<30?0.8:age<40?1.0:age<50?1.2:age<60?1.5:1.8;const planFactor=plan>=4?1.6:plan>=3?1.3:plan>=2?1.0:0.75;const covFactor=cov>=2?2.5:1.0;const monthly=baseMonthly*ageFactor*planFactor*covFactor*(1+smoke)*region;const annual=monthly*12;const oop=ded*2.5;const totalCost=annual+ded;$("health-val").textContent=fmt(monthly)+"/mo";$("hi-annual").textContent=fmt(annual);$("hi-monthly").textContent=fmt(monthly);$("hi-oop").textContent=fmt(oop);$("hi-total").textContent=fmt(totalCost);$("health-st").textContent="PREMIUM ESTIMATE";$("health-st").style.color="#ec4899";let ins=[];ins.push("Estimated premium: <strong>"+fmt(monthly)+"/mo</strong> ("+fmt(annual)+"/yr).");ins.push("With "+fmt(ded)+" deductible, max annual exposure: <strong>"+fmt(totalCost)+"</strong>.");$("health-ins").innerHTML='<h6 class="fw-bold mb-2"><i class="fas fa-lightbulb me-2 text-warning"></i>Analysis</h6><ul class="list-unstyled mb-0 small">'+ins.map(x=>'<li class="mb-2"><i class="fas fa-check-circle text-success me-2"></i>'+x+'</li>').join("")+'</ul>';}['hi-age','hi-plan','hi-ded','hi-cov','hi-smoke','hi-region'].forEach(id=>$(id).addEventListener("input",calc));$("health-cb").addEventListener("click",calc);$("health-cp").addEventListener("click",function(){navigator.clipboard.writeText("Health Insurance Premium Calculator: "+$("health-val").textContent).then(()=>{const o=this.innerHTML;this.innerHTML='<i class="fas fa-check me-2"></i>Copied!';setTimeout(()=>this.innerHTML=o,2e3);});});$("health-rs").addEventListener("click",()=>{$("hi-age").value=40;$("hi-plan").value=2;$("hi-ded").value=2000;$("hi-cov").value=1;$("hi-smoke").value=0;$("hi-region").value=1;calc();});calc();});</script>
<style>.health-insurance-premium-calculator-rebuilt .calculator-card{background:#fff;border:1px solid #e5e7eb;border-radius:20px;padding:2rem;box-shadow:0 4px 24px rgba(0,0,0,.04)}.health-insurance-premium-calculator-rebuilt .calculator-header{display:flex;align-items:center;gap:1.25rem;margin-bottom:2rem}.health-insurance-premium-calculator-rebuilt .calculator-header h4{margin:0;font-weight:700;font-size:1.1rem;color:#1e293b}.health-insurance-premium-calculator-rebuilt .calculator-header p{margin:0;font-size:.85rem;color:#64748b}.health-insurance-premium-calculator-rebuilt .tool-icon-circle{width:56px;height:56px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.4rem;flex-shrink:0}.health-insurance-premium-calculator-rebuilt .form-label-custom{font-size:.75rem;font-weight:700;color:#475569;text-transform:uppercase;letter-spacing:.8px;margin-bottom:.4rem;display:block}</style><?php /**PATH D:\Xamp\htdocs\ToolsHub\resources\views\tools\interactive\health-insurance-premium-calculator.blade.php ENDPATH**/ ?>